  FT["PH-H2547"] = {"id":"PH-H2547","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2820_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Bato市","en":"An Act Creating Certain Barrios in the Municipality of Bato, Province of Catanduanes","orig":"An Act Creating Certain Barrios in the Municipality of Bato, Province of Catanduanes","vi":"Đạo luật thành lập các Barrio tại Đô thị Bato, Tỉnh Catanduanes","th":"พระราชบัญญัติจัดตั้งบาริโอหลายแห่ง ในเทศบาล Bato จังหวัด Catanduanes","id":"Undang-Undang membentuk beberapa Barrio di Kotamadya Bato, Provinsi Catanduanes","ms":"Akta menubuhkan beberapa Barrio di Perbandaran Bato, Wilayah Catanduanes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2820","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2820_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2547-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following sitios in the Municipality of Bato, Province of Catanduanes, are converted into barrios therein, to wit:\n1. Sitio Mintay to Barrio Mintay;\n2. Sitio Carorian to Barrio Carorian; and\n3. Sitio Buenavista to Barrio Buenavista."}},{"id":"PH-H2547-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36"};
  FT["PH-H2548"] = {"id":"PH-H2548","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2821_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Panabo市","en":"An Act Creating Certain Barrios in the Municipality of Panabo, Province of Davao","orig":"An Act Creating Certain Barrios in the Municipality of Panabo, Province of Davao","vi":"Đạo luật thành lập các Barrio tại Đô thị Panabo, Tỉnh Davao","th":"พระราชบัญญัติจัดตั้งบาริโอหลายแห่ง ในเทศบาล Panabo จังหวัด Davao","id":"Undang-Undang membentuk beberapa Barrio di Kotamadya Panabo, Provinsi Davao","ms":"Akta menubuhkan beberapa Barrio di Perbandaran Panabo, Wilayah Davao"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2821","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2821_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2548-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following sitios in the Municipality of Panabo, Province of Davao, are converted or constituted into barrios therein, to wit:\n1. Sitio Magopsing, to be known as the barrio of Magopsing; and\n2. Sitios of Carriedo and New Camiling, into a distinct and independent barrio, to be known as the barrio of Alejal."}},{"id":"PH-H2548-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36"};
  FT["PH-H2549"] = {"id":"PH-H2549","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2822_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"更改达沃省Panabo市镇若干村名称的法案","en":"An Act Changing the Names of Certain Barrios in the Municipality of Panabo, Province of Davao","orig":"An Act Changing the Names of Certain Barrios in the Municipality of Panabo, Province of Davao"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2822","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2822_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2549-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The names of the following barrios in the Municipality of Panabo, Province of Davao, are changed as follows:\n1. Barrio Upper Catungan to Barrio Sta. Cruz; and\n2. Barrio Southern Manay to Barrio Casilac."}},{"id":"PH-H2549-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Names of Certain Barrios in the Municipality of Panabo, Province of Davao","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2550"] = {"id":"PH-H2550","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2823_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将莱特省Liloan市镇Caligangan居民点改设为村的法案","en":"An Act Converting Sitio Caligangan, Municipality of Liloan, Province of Leyte, into a Barrio","orig":"An Act Converting Sitio Caligangan, Municipality of Liloan, Province of Leyte, into a Barrio"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2823","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2823_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2550-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Sitio Caligangan, Municipality of Liloan, Province of Leyte, is hereby converted into a barrio to be known as Barrio Caligangan."}},{"id":"PH-H2550-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Converting Sitio Caligangan, Municipality of Liloan, Province of Leyte, into a Barrio","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2551"] = {"id":"PH-H2551","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2824_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Palompon市","en":"An Act Creating Certain Barrios in the Municipality of Palompon, Province of Leyte","orig":"An Act Creating Certain Barrios in the Municipality of Palompon, Province of Leyte","vi":"Đạo luật thành lập các Barrio tại Đô thị Palompon, Tỉnh Leyte","th":"พระราชบัญญัติจัดตั้งบาริโอหลายแห่ง ในเทศบาล Palompon จังหวัด Leyte","id":"Undang-Undang membentuk beberapa Barrio di Kotamadya Palompon, Provinsi Leyte","ms":"Akta menubuhkan beberapa Barrio di Perbandaran Palompon, Wilayah Leyte"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2824","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2824_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2551-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of Cantandoy, Tambis and Oguinsan in the Municipality of Palompon, Province of Leyte, are converted into barrios of said municipality to be known as the barrios of Cantandoy, Tambis and Oguinsan, respectively."}},{"id":"PH-H2551-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36"};
  FT["PH-H2552"] = {"id":"PH-H2552","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2825_1960.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"在八打雁省第二区设立若干村落的法案","en":"An Act Creating Certain Barrios in the Second District of the Province of Batangas","orig":"An Act Creating Certain Barrios in the Second District of the Province of Batangas"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2825","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2825_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2552-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following sitios in the Municipality of Bauan, Province of Batangas, are constituted as barrios therein to wit:\n(a) The sitio of Look is separated from barrio Culbo and the sitio of Look is separated from barrio Magalangalang, and are constituted into a distinct and independent barrio, to be known as the barrio of Bagong Silang; and\n(b) The sitios of Tubuhan and San Gelacio are separated from the barrio of Malaking Pook, and constituted into a distinct and independent barrio, to be known as the barrio of Resplandor."}},{"id":"PH-H2552-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The following sitios in the Municipality of Batangas, same province, are constituted as barrios therein, to wit:\n(a) Sitio of Pook, barrio Mahabang-Parang, is converted into a barrio, to be known as the barrio of Sorosorong Ilaya, and sitio of Sorosorong Bundoc is converted into a barrio, to be known as the barrio of Sorosorong Ibaba; the boundary line between these barrios shall be a straight line running from East to West passing through the center of the barrio school building of Sorosoro;\n(b) Sitio of Sorosorong Carzada is converted into a barrio, to be known as the barrio of Sorosorong Carzada;\n(c) Sitio Pook ni Mestisa is converted into a barrio, to be known as the barrio of Banabang Silañgan;\n(d) Sitio Ilaya is converted into a barrio, to be known as the barrio of Banabang Ilaya;\n(e) Sitios Magbabanig, Apple and Ibaba are constituted into a distinct and independent barrio, to be known as the barrio of Banabang Ibaba;\n(f) Sitios of Kanluran, Silangang Carzada before Mangahan, Balimbing and Guitnang Pook are constituted into a distinct and independent barrio, to be known as the barrio Banabang Kanluran; and\n(g) The sitio of Saimsim is separated from barrio Haliguing Kanluran, the sitio of Igat is separated from barrio Simlong, and the sitio of Piit is separated from barrio Pinamucan, and are constituted into a distinct and independent barrio, to be known as the barrio of Pinamucan Silangan."}},{"id":"PH-H2552-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating Certain Barrios in the Second District of the Province of Batangas","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
