  FT["PH-H2555"] = {"id":"PH-H2555","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2828_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Naujan市","en":"An Act Creating Certain Barrios in the Municipality of Naujan, Province of Oriental Mindoro","orig":"An Act Creating Certain Barrios in the Municipality of Naujan, Province of Oriental Mindoro","vi":"Đạo luật thành lập các Barrio tại Đô thị Naujan, Tỉnh Oriental Mindoro","th":"พระราชบัญญัติจัดตั้งบาริโอหลายแห่ง ในเทศบาล Naujan จังหวัด Oriental Mindoro","id":"Undang-Undang membentuk beberapa Barrio di Kotamadya Naujan, Provinsi Oriental Mindoro","ms":"Akta menubuhkan beberapa Barrio di Perbandaran Naujan, Wilayah Oriental Mindoro"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2828","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2828_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2555-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following sitios in the Municipality of Naujan, Province of Oriental Mindoro, are separated from their respective barrios and constituted into distinct and independent barrios therein to wit:\n1. The sitios of San Agustin Ilaya, Kabilang Ilog, Mangaya and San Andres of the barrio of San Agustin No. 1, to be known as the barrio of San Agustin;\n2. The sitios of Butik Proper, Labak, Ibulo and Bukayao Grande of the barrio of Tagumpay, to be known as the barrio of San Andres;\n3. The sitios of Arangin Proper, Bagtu ng Arangin, Bansana, Barumbong and Kaowayan of the barrio of Malvar, to be known as the barrio of Arangin; and\n4. The sitios of Paitan, Bandol, Bugayan and Timbolaten of the barrio of Evangelista, to be known as the barrio of Metolza (Paitan)."}},{"id":"PH-H2555-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36"};
  FT["PH-H2556"] = {"id":"PH-H2556","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2829_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立DARaga市","en":"An Act Creating the Barrio of Madaat in the Municipality of DARaga, Province of Albay","orig":"An Act Creating the Barrio of Madaat in the Municipality of DARaga, Province of Albay","vi":"Đạo luật thành lập một Barrio Madaat tại Đô thị DARaga, Tỉnh Albay","th":"พระราชบัญญัติจัดตั้งบาริโอ Madaat ในเทศบาล DARaga จังหวัด Albay","id":"Undang-Undang membentuk sebuah Barrio Madaat di Kotamadya DARaga, Provinsi Albay","ms":"Akta menubuhkan sebuah Barrio Madaat di Perbandaran DARaga, Wilayah Albay"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2829","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2829_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2556-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitio of Madaat in the barrio of San Vicente Grande, Municipality of Daraga, Province of Albay is converted into a barrio of said municipality to be known as the barrio of Madaat."}},{"id":"PH-H2556-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36"};
