  FT["PH-H2561"] = {"id":"PH-H2561","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2834_1960.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Clarin市","en":"An Act Converting the Clarin High School in the Municipality of Clarin, Province of Bohol, into a National School of Fisheries to be Known as the Clarin School of Fisheries, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Converting the Clarin High School in the Municipality of Clarin, Province of Bohol, into a National School of Fisheries to be Known as the Clarin School of Fisheries, and Authorizing the Appropriation of Funds Therefor","vi":"Đạo luật chuyển đổi Clarin High School thành Clarin School of Fisheries","th":"พระราชบัญญัติเปลี่ยนสถานะ Clarin High School เป็น Clarin School of Fisheries","id":"Undang-Undang mengubah Clarin High School menjadi Clarin School of Fisheries","ms":"Akta menukar Clarin High School kepada Clarin School of Fisheries"},"level":"law","status":"active","topics":["environment","education"],"docNumber":"Republic Act No. 2834","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2834_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2561-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Clarin High School in the Municipality of Clarin, Province of Bohol, is hereby converted into a national school of fisheries to be known as the Clarin School of Fisheries. The Secretary of Education is hereby empowered to reorganize said school accordingly."}},{"id":"PH-H2561-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of one hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the conversion, operation and maintenance of said school during the fiscal year nineteen hundred sixty-one. Such sums as may be necessary for its operation and maintenance in subsequent years shall be included in the annual General Appropriations Act."}},{"id":"PH-H2561-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36"};
  FT["PH-H2562"] = {"id":"PH-H2562","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2835_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Midsayap市","en":"An Act Creating Certain Barrios in the Municipality of Midsayap, Province of Cotabato","orig":"An Act Creating Certain Barrios in the Municipality of Midsayap, Province of Cotabato","vi":"Đạo luật thành lập các Barrio tại Đô thị Midsayap, Tỉnh Cotabato","th":"พระราชบัญญัติจัดตั้งบาริโอหลายแห่ง ในเทศบาล Midsayap จังหวัด Cotabato","id":"Undang-Undang membentuk beberapa Barrio di Kotamadya Midsayap, Provinsi Cotabato","ms":"Akta menubuhkan beberapa Barrio di Perbandaran Midsayap, Wilayah Cotabato"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2835","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2835_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2562-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following sitios in the Municipality of Midsayap, Province of Cotabato, are converted into barrios therein to wit:\n1. Sitio Dado to Barrio Dado;\n2. Sitio Central Bulanan (Km. 52) to Barrio Central Bulanan (Km. 52);\n3. Sitio Malamonte to Barrio Malamonte;\n4. Sitio Samlang to Barrio Samlang;\n5. Sitio Kiloyno to Barrio Kiloyno;\n6. Sitio Biacnabato to Barrio Biacnabato;\n7. Sitio Kamanal to Barrio Kamanal; and\n8. Sitio Pacao to Barrio Pacao."}},{"id":"PH-H2562-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36"};
  FT["PH-H2563"] = {"id":"PH-H2563","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2836_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Dumingag市","en":"An Act Creating Certain Barrios in the Municipality of Dumingag, Province of Zamboanga del Sur","orig":"An Act Creating Certain Barrios in the Municipality of Dumingag, Province of Zamboanga del Sur","vi":"Đạo luật thành lập các Barrio tại Đô thị Dumingag, Tỉnh Zamboanga del Sur","th":"พระราชบัญญัติจัดตั้งบาริโอหลายแห่ง ในเทศบาล Dumingag จังหวัด Zamboanga del Sur","id":"Undang-Undang membentuk beberapa Barrio di Kotamadya Dumingag, Provinsi Zamboanga del Sur","ms":"Akta menubuhkan beberapa Barrio di Perbandaran Dumingag, Wilayah Zamboanga del Sur"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2836","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2836_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2563-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of Gumpingan and Lipawan in the Municipality of Dumingag, Province of Zamboanga del Sur, are converted into barrios of said municipality to be known as barrio of Gumpingan and barrio of Lipawan, respectively."}},{"id":"PH-H2563-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36"};
