  FT["PH-H2570"] = {"id":"PH-H2570","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2843_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"宣布打拉省La Paz市镇若干地点为依法设立的村的法案","en":"An Act Declaring Certain Places in the Municipality of La Paz, Province of Tarlac, as Duly Constituted Barrios","orig":"An Act Declaring Certain Places in the Municipality of La Paz, Province of Tarlac, as Duly Constituted Barrios"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2843","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2843_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2570-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following places in the Municipality of La Paz, Province of Tarlac, are declared as duly constituted barrios therein, to wit:\n1. Balanoy as barrio Balanoy;\n2. Bantog-Caricutan as barrio Bantog-Caricutan,\n3. Caramutan as barrio Caramutan;\n4. Caut as barrio Caut;\n5. Gomillas as barrio Gomillas, with the sitio of Riolova as part thereof;\n6. Dumarais as barrio Dumarais;\n7. Guevara as barrio Guevara, with the sitio of Particion as part thereof;\n8. Kapanikian as barrio Kapanikian;\n9. Lara as barrio Lara;\n10. Laungcupang as barrio Laungcupang;\n11. Lomboy as barrio Lomboy, with the sitio of Mapalad as part thereof;\n12. Macalong as barrio Macalong;\n13. Matayumtayum as barrio Matayumtayum;\n14. Mayang as barrio Mayang;\n15. Motrico as barrio Motrico;\n16. Paludpud as barrio Paludpud;\n17. La Purisima (Pulongcawayan) as barrio La Purisima;\n18. San Isidro as barrio San Isidro;\n19. San Roque as barrio San Roque, with the sitio of Libtong as part thereof; and\n20. Sierra as barrio Sierra."}},{"id":"PH-H2570-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Declaring Certain Places in the Municipality of La Paz, Province of Tarlac, as Duly Constituted Barrios","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
