  FT["PH-H2589"] = {"id":"PH-H2589","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2862_1960.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Gamay市","en":"An Act Converting the Gamay Junior High School in the Municipality of Gamay, Province of Samar, into a Vocational School to be Known as the Gala Vocational High School, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Converting the Gamay Junior High School in the Municipality of Gamay, Province of Samar, into a Vocational School to be Known as the Gala Vocational High School, and Authorizing the Appropriation of Funds Therefor","vi":"Đạo luật chuyển đổi Gamay Junior High School thành Gala Vocational High School","th":"พระราชบัญญัติเปลี่ยนสถานะ Gamay Junior High School เป็น Gala Vocational High School","id":"Undang-Undang mengubah Gamay Junior High School menjadi Gala Vocational High School","ms":"Akta menukar Gamay Junior High School kepada Gala Vocational High School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 2862","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2862_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2589-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Gamay Junior High School in the Municipality of Gamay, Province of Samar, is converted into a vocational school to be known as the Gala Vocational High School which shall be under the supervision of the Director of Public Schools."}},{"id":"PH-H2589-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of one hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said school."}},{"id":"PH-H2589-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36"};
  FT["PH-H2590"] = {"id":"PH-H2590","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2863_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Enrile市","en":"An Act Creating Certain Barrios in the Municipality of Enrile, Province of Cagayan","orig":"An Act Creating Certain Barrios in the Municipality of Enrile, Province of Cagayan","vi":"Đạo luật thành lập các Barrio tại Đô thị Enrile, Tỉnh Cagayan","th":"พระราชบัญญัติจัดตั้งบาริโอหลายแห่ง ในเทศบาล Enrile จังหวัด Cagayan","id":"Undang-Undang membentuk beberapa Barrio di Kotamadya Enrile, Provinsi Cagayan","ms":"Akta menubuhkan beberapa Barrio di Perbandaran Enrile, Wilayah Cagayan"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2863","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2863_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2590-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of Liwan Sur, Liwan Norte and Roma in the Municipality of Enrile, Province of Cagayan, are converted into barrios of said municipality, to be known as the barrios of San Agustin, San Luis and Roma, respectively."}},{"id":"PH-H2590-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36"};
  FT["PH-H2591"] = {"id":"PH-H2591","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2864_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将卡加延省Enrile市镇Dammang居民点的名称正式变更为San Juan的法案","en":"An Act Changing the Name of the Sitio of Dammang in the Municipality of Enrile, Province of Cagayan, to San Juan","orig":"An Act Changing the Name of the Sitio of Dammang in the Municipality of Enrile, Province of Cagayan, to San Juan","vi":"Đạo luật đổi tên Sitio Dammang tại Thị trấn Enrile, Tỉnh Cagayan thành San Juan","th":"พระราชบัญญัติเปลี่ยนชื่อซิติโอ Dammang ในเทศบาล Enrile, จังหวัด Cagayan เป็น San Juan","id":"Undang-Undang mengubah nama Sitio Dammang di Kotamadya Enrile, Provinsi Cagayan menjadi San Juan","ms":"Akta menukar nama Sitio Dammang di Perbandaran Enrile, Wilayah Cagayan menjadi San Juan"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2864","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2864_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2591-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the sitio of Dammang in the Municipality of Enrile, Province of Cagayan, is changed to San Juan."}},{"id":"PH-H2591-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of the Sitio of Dammang in the Municipality of Enrile, Province of Cagayan, to San Juan","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2592"] = {"id":"PH-H2592","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2865_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"公共工程拨款法案","en":"An Act Appropriating Funds for Public Works","orig":"An Act Amending a Certain Item of Republic Act Numbered Fourteen Hundred and Eleven, Entitled “An Act Appropriating Funds for Public Works”"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2865","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2865_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2592-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Item 9, under Group III for the Province of Batangas, page 286, Section three of Republic Act Numbered Fourteen hundred and eleven is hereby amended to read as follows:\n\"9. San Miguel Barrio School, Padre Garcia—Construction and/or improvement ₱6,000.00 \"9-A Padre Garcia Central School building—Construction and improvement 4,000.00.\""}},{"id":"PH-H2592-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Appropriating Funds for Public Works","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2593"] = {"id":"PH-H2593","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2866_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将第1613号共和国法项下用于朗布隆Cajidiocan Ayahag建造一间教室的预制校舍的2600比索拨款转给同市镇Cantagda的法案","en":"An Act Transferring the Appropriation of Two Thousand Six Hundred Pesos for the Construction of a One-Room Prefabricated School Building in Ayahag, Cajidiocan, Romblon, Under Republic Act Numbered Sixteen Hundred and Thirteen, to Cantagda of the Same Municipality","orig":"An Act Transferring the Appropriation of Two Thousand Six Hundred Pesos for the Construction of a One-Room Prefabricated School Building in Ayahag, Cajidiocan, Romblon, Under Republic Act Numbered Sixteen Hundred and Thirteen, to Cantagda of the Same Municipality"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 2866","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2866_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2593-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Priority 31, for the Province of Romblon, under School Building Schedules, Appendix B of Republic Act Numbered Sixteen hundred and thirteen, is amended to read as follows:\n\"31 Cajidiocan Cantagda Construction of one room prefabricated. 2,600.00"}},{"id":"PH-H2593-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p36","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Transferring the Appropriation of Two Thousand Six Hundred Pesos for the Construction of a One-Room Prefabricated School Building in Ayahag, Cajidiocan, Romblon, Under Republic Act Numbered Sixteen Hundred and Thirteen, to Cantagda of the Same Municipality","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2594"] = {"id":"PH-H2594","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2867_1960.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"在东米萨米斯省若干市镇设立村社的法案","en":"An Act Creating Barrios in Certain Municipalities of the Province of Misamis Oriental","orig":"An Act Creating Barrios in Certain Municipalities of the Province of Misamis Oriental"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2867","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2867_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2594-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following sitios in the Municipality of Salay, Province of Misamis Oriental, are constituted as barrios of said municipality, to wit:\n1. The sitios of Kasolog, Limpatogno, Tagongtong, Bobolotan, Olo-olo, Salagbanog, Kimaloc and Ta-as, into a distinct and independent barrio, to be known as the barrio of Poblacion;\n2. The sitios of Tayondo, Tinigbasan, Malinao, Dongdonga-an, Pigsigayan, Kalitsi-an and Ili-ilihan, into a distinct and independent barrio, to be known as the barrio of Alipuaton;\n3. The sitios of Kibalaring, Dinagsa-an, Kabunotan, Bagyangan, Kogon, Hologan and Lumad, into a distinct and independent barrio, to be known as the barrio of Amponican;\n4. The sitios of Minpipi, Naratulan, Ki-idiang, Upper Binuangan and Punta, into a distinct and independent barrio, to be known as the barrio of Binuangan;\n5. The sitios of Capongocan, Batangan, Tomangcal, Kitadias, Tunga and Katalia, into a distinct and independent barrio, to be known as the barrio of Looc;\n6. The sitios of Gantangon, Tinigbasa and Kabonongan, into a distinct and independent barrio, to be known as the barrio of Mabini;\n7. The sitios of Kamonomonohan and Silad, into a distinct and independent barrio, to be known as the barrio of Valdeconcha;\n8. The sitios of Inubolan del Sur, Bulwa, Kabologohan, Kibalaring, Inubolan del Norte and Ilihan, into a distinct and independent barrio, to be known as the barrio of Inubolan;\n9. The sitios of Binangko-an, Pag-ongawan, Ili-ilihan, Mindulohan, Malamoni, Kinoralan and Salibot, into a distinct and independent barrio, to be known as the barrio of Saray;\n10. The sitios of Mangkita, Kanangka-an, Tag-inoman and Guindalohan, into a distinct and independent barrio, to be known as the barrio of Yongod;\n11. The sitios of Laalawan, Luginit, Bunal, Saluagan, Tangantongan, Kalaysaoy, Tolho-on, Pagahan, (Kamarsikohan-San Vicente) Sago-abang, Damdamon, Pig-olohan, Nabo-ongan and Kabagakayan, into a distinct and independent barrio, to be known as the barrio of Tinaga-an;\n12. The sitios of Nabogo, Kabunto, Komagaycay, Dalahikan, Tulabaga and Catarman, into a distinct and independent barrio, to be known as the barrio of Mosangot;\n13. The sitios of Poyo, Higyop, Malitawo, Mapuwang Yuta Kabalongkot, Nabo-olan, Matampa, Nabalabag, Pangcalan, Kalambagohan, Amorsikohan and Kalisawon, into a distinct and independent barrio, to be known as the barrio of Guinalaban;\n14. The sitios of Mimbulo, Minkokok, Malamoni and Bulwa, into a distinct and independent barrio, to be known as the barrio of Salay River Side I and Side II;\n15. The sitios of Nabata-an and Kimamoan, into a distinct and independent barrio to be known as the barrio of Dampias;\n16. The sitios of Komagaycay, Buhawi and Kibatiao, into a distinct and independent barrio, to be known as the barrio of Kitamban; and\n17. The sitios of Silad, Ka-odtohan and Kolambog, into a distinct and independent barrio, to be known as the barrio of Salagaag."}},{"id":"PH-H2594-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sitio of Gasi in the Municipality of Alubijid, same province, is converted into a barrio of said municipality, to be known as the barrio of Gasi."}},{"id":"PH-H2594-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The following sitios in the Municipality of Magsaysay, same province, are constituted as barrios therein, to wit:\n1. The sitios of Tab-angan, Minsalag, Biasong and Timaya, into a distinct and independent barrio, to be known as the barrio of Consuelo;\n2. The sitios of Maykawayan, Sandiis, Macupa and Calangian, into a distinct and independent barrio, to be known as the barrio of Panigan;\n3. The sitios of Guipawa, Mintugas and Tumagubtub, into a distinct and independent barrio, to be known as the barrio of Artadi;\n4. The sitios of Sabatan, Calin-oban, Hopocan, Binagyohan, Babag and Kiburo, into a distinct and independent barrio, to be known as the barrio of Kibunsod;\n5. The sitios of Labasican, Bimangoaan, Kilombo, Mindulao and Abunda, into a distinct and independent barrio, to be known as the barrio of Cabalawan;\n6. The sitios of Minbita-ag, Tinaan, Otop, Guibetohan, Basacan and Bunawan, into a distinct and independent barrio, to be known as the barrio of Bumabon;\n7. The sitios of Calingahan, Gauswagan, Pagalaran, Lilo and Lita, into a distinct and independent barrio, to be known as the barrio of Cabubuhan;\n8. The sitios of Balacayo and Minbatlog, into a distinct and independent barrio, to be known as the barrio of Looc;\n9. The sitios of Mingamut, Min-ipil and Mahayahay, into a distinct and independent barrio, to be known as the barrio of Damayohan;\n10. The sitios of Baculod, Kibaoto, Peligosos, Tambugawi and Tambaculoag, into a distinct and independent barrio, to be known as the barrio of San Isidro;\n11. The sitios of Baylanon and La Union, into a distinct and independent barrio, to be known as the barrio of Tulang;\n12. The sitios of Binalbalan and Sinablayan, into a distinct and independent barrio, to be known as the barrio of Poblacion; and\n13. The sitios of Balacanasan, Tuhog, Calabonton, Upper Gosoo Daon, Upper Gosoon Camay and Donafor Crossing into a distinct and independent barrio, to be known as the barrio of Hiwata."}},{"id":"PH-H2594-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The following sitios in the Municipality of Opol, same province, are constituted as barrios therein, to wit:\n1. The sitios of Malanang, Masagpi-an, Taporok, Dugyanggan, Tulahon, Camarok, Anilao, Binagwayan and Mansilop, into a distinct and independent barrio, to be known as the barrio of Malanang;\n2. The sitios of Patag, Balabag, Mamis, Eco, Lagacdang, Toling, Cusa, Calamtog, Cakungahan, Saging, Punta and Maapo, into a distinct and independent barrio, to be known as the barrio of Patag;\n3. The sitios of Bagoktok, Tagsulip, Limatocon, Bayugtayugan, Basak, Awang, Ilongay, Tingalan, Tinaguman, Arao-araw, Nalunoran and Impaquivil, into a distinct and independent barrio, to be known as the barrio of Bagoktok;\n4. The sitios of Nangca-on, Gaogawon, Tagkolot, Pigtao, Dumalokdok, Guimtuloran, Bostong and Gusi, into a distinct and independent barrio, to be known as the barrio of Nangca-on; and\n5. The sitios of Cauyonan, Candi-isan, Tala-ili, Lumayagan, Pangdiwatan, Capisahan, Buyatak, Lindatan, Batangan, and West of Pigsag-an into a distinct and independent barrio, to be known as the barrio of Canyosan."}},{"id":"PH-H2594-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating Barrios in Certain Municipalities of the Province of Misamis Oriental","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2595"] = {"id":"PH-H2595","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2868_1960.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"在达沃省若干市镇设立街区的法案","en":"An Act Creating Barrios in Certain Municipalities of the Province of Davao","orig":"An Act Creating Barrios in Certain Municipalities of the Province of Davao"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2868","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2868_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2595-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The place known as Ceboza is separated from the poblacion of the Municipality of Matanao, Province of Davao, and is constituted into a distinct and independent barrio of said municipality, to be known as the barrio of Ceboza."}},{"id":"PH-H2595-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sitio of Sta. Cruz in the Municipality of Asuncion, same province, is converted into a barrio of said municipality, to be known as the barrio of Sta. Cruz."}},{"id":"PH-H2595-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sitio of Cacao in the Municipality of Panabo, same province, is converted into a barrio of said municipality, to be known as the barrio of Cacao."}},{"id":"PH-H2595-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating Barrios in Certain Municipalities of the Province of Davao","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2596"] = {"id":"PH-H2596","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2869_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"公共工程拨款并为其他目的法案","en":"An Act Appropriating Funds for Public Works and for Other Purposes","orig":"An Act Amending Certain Items of Republic Act Numbered Twenty-Three Hundred and One, Entitled “An Act Appropriating Funds for Public Works and for Other Purposes”"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2869","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2869_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文条号不连续（自第 1 条起，止于第 3 条，缺 2）：经逐条比对原始页面，该处原文没有对应的 “Section N.” 抬头行，系来源页自身的编号跳跃或条文以“续段”形式并入前条，非抽取遗漏，故未擅自补号。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2596-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"On page 154 of Republic Act Numbered Twenty-three hundred and one, item (23) under Group II (Projects for the Second District, Negros Oriental), embraced by subsection c (Re implementation of Republic Act Numbered Eight hundred thirty-six, as amended), is hereby amended to read as follows:\n\"(23) Central Primary School Building, Siquijor—Improvement ₱5,000.00\"\nSection 2. On page 441 of the same Act, item (k) under Group II (Projects for the Second District, Negros Oriental), under subsection d of Section two thereof, is hereby amended to read as follows:\n\"(k) Central Primary School, Siquijor—Aid to PTA for improvement ₱5,000.00\""}},{"id":"PH-H2596-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Appropriating Funds for Public Works and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2597"] = {"id":"PH-H2597","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2870_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"公共工程拨款并为其他目的法案","en":"An Act Appropriating Funds for Public Works and for Other Purposes","orig":"An Act Amending a Certain Item of Republic Act Numbered Sixteen Hundred and Thirteen, Entitled “An Act Appropriating Funds for Public Works and for Other Purposes”"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2870","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2870_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2597-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"On page 70-B of Appendix B (re implementation of Republic Act Numbered Eight hundred thirty-six, as amended) of Republic Act Numbered Sixteen hundred and thirteen, Item 15, under Group II (Projects for the Second District, Negros Oriental), is hereby amended to read as follows:\n\"15. Maria-Bogo—Construction and improvement ₱5,000.00\""}},{"id":"PH-H2597-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Appropriating Funds for Public Works and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2598"] = {"id":"PH-H2598","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2871_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Anilao市","en":"An Act Creating Certain Barrios in the Municipality of Anilao, Province of Iloilo","orig":"An Act Creating Certain Barrios in the Municipality of Anilao, Province of Iloilo","vi":"Đạo luật thành lập các Barrio tại Đô thị Anilao, Tỉnh Iloilo","th":"พระราชบัญญัติจัดตั้งบาริโอหลายแห่ง ในเทศบาล Anilao จังหวัด Iloilo","id":"Undang-Undang membentuk beberapa Barrio di Kotamadya Anilao, Provinsi Iloilo","ms":"Akta menubuhkan beberapa Barrio di Perbandaran Anilao, Wilayah Iloilo"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2871","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2871_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2598-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following sitios in the Municipality of Anilao, Province of Iloilo, are constituted and declared as barrios therein, to wit:\nThe sitios of Janicaman Ilaya, Dinum-at Bugas, Cantoy, Bobog, H. Lourdes and Buena Lastima, into a distinct and independent barrio, to be known as the barrio of Poblacion;\nThe sitios of Binun-an Sulod and Janicaman Ilawod, into a distinct and independent barrio, to be known as the barrio of Pantalan;\nThe sitios of Pangpang Norte, Pangpang Sur, Ilawod Sur, Moros, Baluarte and Balañga-an, into a distinct and independent barrio, to be known as the barrio of Sta. Rita;\nThe sitios of Bato, Bat-us, Himogbugan and Mumwick, into a distinct and independent barrio, to be known as the barrio of Dangula-an;\nThe sitios of Laligan, Lu-awan, Bogtong Bukid, Payud, Dalipe Sur, Guibuañgan Sur and Bariñgan Sur, into a distinct and independent barrio, to be known as the barrio of San Carlos;\nThe sitios of Orioegan, Alibayug Ilawod, Agloy-a Ilawod, Aglankawas, Hulot and Suyakan, into a distinct and independent barrio, to be known as barrio of Manganese;\nThe sitios of Marka Bobog, Agtambo, Olo Anilao, Anilao Cayo, Orol and Mangiyakiya, into a distinct and independent barrio, to be known as the barrio of Balunos;\nThe sitios of Buenavista, Guintapukan, Inadlawan, Kabangkalan, Tangcong, Dalipe, Lampuyang, Sibucawan and Guiraguid, into a distinct and independent barrio, to be known as the barrio of Cag-an;\nThe sitios of Pangurayan, Kapaclan, Lininti-an, Badiaoegan and Agpandan Daku, into a distinct and independent barrio, to be known as the barrio of Mostro;\nThe sitios of Guintingfi Sta. Ana Sulod, Amador, Kaliburan, Boyongan Talus and Linao Kalayo, into a distinct and independent barrio, to be known as the barrio of Palaypay;\nThe sitios of Bacolod, Bonsod Norte, Hda. San Marcelino, Bairan Sur and Patio, into a distinct and independent barrio, to be known as the barrio of Sabang Culob;\nThe sitios of Bonsod Sur, Balagon, Igang and Botitihon, into a distinct and independent barrio, to be known as the barrio of Badiang;\nThe sitios of Biga-a and Plantation No. 1, into a distinct and independent barrio, to be known as the barrio of Serallo;\nThe sitios of Odok, Kadugang and Genis Bukid, into a distinct and independent barrio, to be known as the barrio of Medina;\nThe sitios of Agtalus, Ilawad, Trencera, and Genis Punta Andagao, into a distinct and independent barrio, to be known as the barrio of San Juan Crisostomo;\nThe sitios of Bairan, Baguio, Agtalus, Ilaya and Genis Olo Agbatuan, into a distinct and independent barrio, to be known as the barrio of Agbatuan;\nThe sitios of Pitogo, Manise Ilaya, Bagongbong and Olo Pitogo, into a distinct and independent barrio, to be known as the barrio of Vista Alegre;\nThe sitios of Manise Ilawod, Bognay, Kangong, Talangban and Dumingding, into a distinct and independent barrio, to be known as the barrio of Camiros;\nThe sitios of Namatay, Lanawon, Ilaho, Kagnayahan, Bacolod Kalubihan and Guinbalayan Ato, into a distinct and independent barrio, to be known as the barrio of Sto. Rosario;\nThe sitios of Aglay-ao, Malublub and Agbalatong, into a distinct and independent barrio, to be known as the barrio of Balabag; and The sitios of Agcarope, Apao, Aladedhan, Agloy-a Ilaya, Alibuyug and Agbatasan, into a distinct and independent barrio, to be known as the barrio of Guipes."}},{"id":"PH-H2598-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36"};
  FT["PH-H2599"] = {"id":"PH-H2599","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2872_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将巴拉望省 罗哈斯市镇 San Vicente村移交给Same省 普林塞萨港市镇的法案","en":"An Act Transferring the Barrio of San Vicente in the Municipality of Roxas, Province of Palawan, to the Municipality of Puerto Princesa, Same Province","orig":"An Act Transferring the Barrio of San Vicente in the Municipality of Roxas, Province of Palawan, to the Municipality of Puerto Princesa, Same Province"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2872","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2872_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2599-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The barrio of San Vicente in the Municipality of Roxas, Province of Palawan, is separated from said municipality, and is transferred to and made part of the Municipality of Puerto Princesa, same province."}},{"id":"PH-H2599-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Transferring the Barrio of San Vicente in the Municipality of Roxas, Province of Palawan, to the Municipality of Puerto Princesa, Same Province","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
